  min-height: 40px !important;
  border-top: none !important; /* 移除原来的灰色顶部线条 */
  background: transparent !important; /* 强制背景透明 */
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* 暴力兜底顶栏透明化（防止变量未完全覆盖部分主题框架） */
.chat-detail-header-custom, .chat-header-custom, .chat-header {
  background: transparent !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  border-bottom: none !important;
  box-shadow: none !important;
}

/* 加号+输入胶囊外层容器：弹性布局，让输入框占满剩余宽度 */
.input-row-wrapper {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  width: 100% !important;
}

/* ======================================= */
/* 核心：输入框胶囊本体附加玻璃质感与布局   */
/* ======================================= */
.input-action-bar-custom {
  flex: 1 !important;
  display: flex !important;
  align-items: center !important;
  gap: 4px !important;
  padding: 0 8px !important;
  height: 32px !important;
  /* 应用冰透胶囊背景和毛玻璃模糊 */
  background: var(--input-box-bg) !important;
  border: var(--input-box-border) !important;
  backdrop-filter: blur(10px) !important;
  -webkit-backdrop-filter: blur(10px) !important;
  border-radius: 16px !important;
  position: relative !important; /* 为自定义提示语提供像素级定位基准 */
}

/* 输入框本体：缩小高度，自适应宽度，无额外内边距 */
.input-box-custom {
  flex: 1 !important;
  height: 28px !important;
  padding: 0 6px !important;
  font-size: 13px !important;
  line-height: 28px !important;
  background: transparent !important;
  border: none !important;
  color: #000 !important;
}

/* ======================================= */
/* 输入框提示语：强制自定义替换并靠左对齐   */
/* ======================================= */

/* 1. 将系统原生的提示语"消息..."透明化隐藏 */
.input-box-custom::placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}

/* 2. 方案兜底 (兼容原生Input标签)应用冰透字色 */
.input-action-bar-custom:has(.input-box-custom:placeholder-shown)::after {
  content: "世界第一小缘..." !important;
  position: absolute !important;
  /* 精确左边距测算: 胶囊左内边距8px + 输入框左内边距6px = 恰好14px紧靠左边 */
  left: 14px !important; 
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: rgba(0, 0, 0, 0.5) !important; /* 匹配冰透主题的半透黑字色 */
  font-size: 12px !important;
  pointer-events: none !important;
}

/* ======================================= */
/* 左侧加号自定义图标替换                   */
/* ======================================= */
.input-btn-plus svg { 
  display: none !important; /* 隐藏原生SVG图标 */
}

/* 加号按钮：自定义图片背景 */
.input-btn-plus {
  width: 32px !important;
  height: 32px !important;
  flex: none !important;
  background-image: url('https://i.postimg.cc/C1Qz60DF/retouch-2026032622105749.png') !important;
  background-size: 26px 26px !important; /* 图标缩放大小 */
  background-repeat: no-repeat !important;
  background-position: center !important;
  background-color: transparent !important;
  box-shadow: none !important;
}

/* ======================================= */
/* 右侧三个图标：隐形触控盲区 (纯透明保留点击)*/
/* ======================================= */
.input-btn-mic, .input-btn-sticker, .input-btn-ai {
  width: 24px !important;
  height: 24px !important;
  opacity: 0 !important; /* 核心：只做透明化，点击功能正常 */
}

/* 右侧按钮组容器：紧贴输入框，无额外间距 */
.input-btns-right {
  display: flex !important;
  align-items: center !important;
  gap: 6px !important;
  flex: none !important;
}

/* 发送按钮：无背景直接融合进胶囊 */
.send-btn-custom {
  width: 28px !important;
  height: 28px !important;
  color: #000 !important;
  flex: none !important;
  background: transparent !important;
  box-shadow: none !important;
}
